// Wall leakage and foreground body radiance belong to different physical domains.
// Foreground pixels remain included in the fixed-image fidelity/contrast tests.
export function assessProjector(d,sim,viewOptions={}){const wallQuality=evaluateProjector(d,sim);if(d.q.layout!=='integrated')return{quality:wallQuality,wallQuality,viewQuality:null,viewSim:null};const viewSim=traceView(d,sim,{distance:d.p.viewDistance,bodyReflectance:d.p.bodyReflectance,lightingSamples:sim.samples,...viewOptions}),v=evaluateProjector(d,viewSim),reasons=[];if(![v.iou,v.edgeF1,v.contrast].every(Number.isFinite))reasons.push('Ошибка проверки видимости');if(v.iou<.85)reasons.push('Корпус скрывает слишком много рисунка');if(v.edgeF1<.8)reasons.push('Потеря контуров в видимой композиции');if(v.contrast<.55)reasons.push('Недостаточный контраст видимой композиции');const viewQuality={iou:v.iou,edgeF1:v.edgeF1,contrast:v.contrast,accepted:reasons.length===0,reasons,bodyRadianceOutsideWindow:v.leakage,assumedBodyReflectance:d.p.bodyReflectance,distanceMM:d.p.viewDistance,wallLeakageIsSeparate:true};return{wallQuality,viewQuality,viewSim,quality:{...v,leakage:wallQuality.leakage,accepted:wallQuality.accepted&&viewQuality.accepted,reasons:[...wallQuality.reasons,...reasons],score:.5*wallQuality.score+.5*(.55*v.iou+.3*v.edgeF1+.15*v.contrast),source:'fixed raw target; direct wall + finite-camera composite; assumed matte material'}};}
